#include <iostream>
#include <vector>
#include <string>
#include <string>
using namespace std;

vector<int> prefixFunction(const string& s) {
    int n = (int)s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
    return pi;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    cin >> s;

    int n = (int)s.size();
    vector<int> pi = prefixFunction(s);
    string body;
    long long count = 0;
    for (int L = 2; L <= n; L++) {
        int p = L - pi[L - 1];
        if (pi[L - 1] > 0 && L % p == 0) {
            count++;
            body += to_string(L) + " " + to_string(L / p) + "\n";
        }
    }
    cout << count << "\n" << body;

    return 0;
}

